package dev.elide.myna.backend;

import dev.elide.myna.model.Seam.*;
import dev.elide.myna.model.Seam.Module;
import java.util.*;

/**
 * Consumer-owned SVM lifecycle integration; no prescribed GC registration or disposal mechanism.
 */
public final class NativeOwnership implements Backend {
  public String filename(Module m) {
    return m.ownershipClass() + ".java";
  }

  public String generate(Module m) {
    var out =
        new StringBuilder(
            "// Generated by myna. Lifecycle implementations are supplied by the consumer.\n"
                + "package "
                + m.javaPackageName()
                + ";\n\npublic final class "
                + m.ownershipClass()
                + " {\n    private "
                + m.ownershipClass()
                + "() {}\n");
    if (!m.ownedResources().isEmpty())
      out.append(
"""
        /** Called exactly once by the consumer when its resource is no longer accessible. */
        @FunctionalInterface
        public interface NativeDestructor { void destroy(long address); }

        /**
         * Takes sole ownership on successful return. On exception, ownership stays with the generator.
         * Must return a non-null owner. Failed adoption must undo registrations without freeing address.
         * The consumer manages GC registration, access guards, and exactly-once destruction.
         * requiredThread is null for shared resources; otherwise access AND destruction require it.
         */
        @FunctionalInterface
        public interface ResourceFactory<T> {
            T adopt(long address, NativeDestructor destructor, java.lang.Thread requiredThread);
        }

""");
    for (Resource r : m.ownedResources()) {
      if (m.outPointer(r)) {
        Function first =
            m.functions().stream()
                .filter(f -> f.name().equals(r.creates().getFirst()))
                .findFirst()
                .orElseThrow();
        out.append("    public static final class ")
            .append(r.name())
            .append(" {\n        private ")
            .append(r.name())
            .append("() {}\n")
            .append(
                "        /**\n"
                    + "         * What a constructor returns for a status outside its success"
                    + " list, when it created\n"
                    + "         * nothing. The out slot is ignored then.\n"
                    + "         */\n"
                    + "        @FunctionalInterface\n"
                    + "        public interface Failure<T> { T failed(")
            .append(NativeImage.qualifiedCarrier(m, first.returns()))
            .append(" status); }\n");
      } else
        out.append("    public static final class ")
            .append(r.name())
            .append(" {\n        private ")
            .append(r.name())
            .append("() {}\n");
      out.append("        private static final NativeDestructor DESTRUCTOR = address -> ")
          .append(m.nativeClass())
          .append('.')
          .append(r.destroy())
          .append("(org.graalvm.word.WordFactory.pointer(address));\n");
      for (String name : r.creates()) {
        Function create =
            m.functions().stream().filter(f -> f.name().equals(name)).findFirst().orElseThrow();
        // A held borrow outlives the call, which only a Truffle cell can express.
        if (m.borrows().stream().anyMatch(b -> b.held() && b.function().equals(name))) continue;
        if (m.callBorrows().stream().anyMatch(b -> b.function().equals(name))) {
          // The buffer wrappers of the import lend each buffer for the call only.
          String target = m.ownershipClass() + "." + name;
          constructor(m, r, name, create, "NativeBuffer", target, out);
          constructor(m, r, name, create, "byte[]", target, out);
        } else constructor(m, r, name, create, null, m.nativeClass() + "." + name, out);
      }
      out.append(
              "        /** Transfer sole ownership of a live allocation with no outstanding"
                  + " borrows. */\n")
          .append(
              "        public static <T> T adoptUnsafe(long address, ResourceFactory<T> factory)"
                  + " {\n")
          .append("            java.util.Objects.requireNonNull(factory);\n")
          .append(
              "            if (address == 0) throw new IllegalArgumentException(\"null"
                  + " resource\");\n")
          .append(
              "            try {\n"
                  + "                return java.util.Objects.requireNonNull(factory.adopt(address,"
                  + " DESTRUCTOR, ")
          .append(r.shared() ? "null" : "java.lang.Thread.currentThread()")
          .append(
              "));\n"
                  + "            } catch (RuntimeException | Error failure) {\n"
                  + "                DESTRUCTOR.destroy(address);\n"
                  + "                throw failure;\n"
                  + "            }\n"
                  + "        }\n"
                  + "    }\n");
    }
    if (!m.callBorrows().isEmpty())
      out.append(
"""
        /**
         * Consumer-owned off-heap bytes. A successful acquire keeps address/size stable and live
         * until release; writable access must be exclusive, read access must prevent mutation.
         * acquire may throw without acquiring; release must not throw. Views may share an owner.
         * A consumer with an externally guaranteed lifetime may implement these hooks as no-ops.
         */
        public interface NativeBuffer {
            void acquire(boolean writable);
            long address();
            long byteSize();
            void release(boolean writable);
        }

""");
    // A C string alone gets no Native Image wrapper: it passes as the raw CCharPointer.
    for (CallBorrows call : CallBorrows.of(m)) if (!call.borrows().isEmpty()) buffers(m, call, out);
    return out.append("}\n").toString();
  }

  /**
   * One constructor of a resource: {@code create} for a resource's only constructor, the import's
   * name otherwise. With {@code buffer} set, each call-borrowed buffer takes that carrier, its
   * length drops out, and {@code target} is the import's buffer wrapper of the same carriers.
   */
  private static void constructor(
      Module m,
      Resource r,
      String name,
      Function create,
      String buffer,
      String target,
      StringBuilder out) {
    CallBorrows call = CallBorrows.of(m, create);
    var params = new ArrayList<String>();
    var args = new ArrayList<String>();
    // Pointer arguments keep the raw binding's carriers, typed records and opaques included.
    for (int i = 0; i < create.parameters().size(); i++) {
      Parameter p = create.parameters().get(i);
      if (buffer != null && call.length(p) != null) continue;
      boolean outPointer = m.outPointer(r);
      // The out slot is the constructor's own: one word on its stack frame.
      if (outPointer && p.name().equals(r.handleParameter())) {
        args.add("org.graalvm.word.WordFactory.pointer(slot.rawValue())");
        continue;
      }
      String carrier =
          buffer != null && call.buffer(p) != null
              ? buffer
              : NativeImage.qualifiedCarrier(m, p.type());
      params.add(carrier + " arg" + i);
      args.add("arg" + i);
    }
    if (m.outPointer(r)) {
      var succeeded = new ArrayList<String>();
      String status = NativeImage.qualifiedCarrier(m, create.returns());
      for (long value : r.success())
        succeeded.add("status == " + value + (status.equals("long") ? "L" : ""));
      out.append(
              "        /** A status outside the success list goes to onFailure, and nothing is"
                  + " adopted. */\n")
          .append("        public static <T> T ")
          .append(r.wrapperName(name))
          .append("(ResourceFactory<T> factory, Failure<? extends T> onFailure")
          .append(params.isEmpty() ? "" : ", " + String.join(", ", params))
          .append(") {\n")
          .append("            java.util.Objects.requireNonNull(factory);\n")
          .append("            java.util.Objects.requireNonNull(onFailure);\n")
          .append(
              "            org.graalvm.word.Pointer slot ="
                  + " org.graalvm.nativeimage.StackValue.get(8);\n")
          .append("            slot.writeLong(0, 0L);\n")
          .append("            ")
          .append(status)
          .append(" status = ")
          .append(target)
          .append('(')
          .append(String.join(", ", args))
          .append(");\n")
          .append("            if (!(")
          .append(String.join(" || ", succeeded))
          .append(")) return onFailure.failed(status);\n")
          .append("            long address = slot.readLong(0);\n")
          .append("            if (address == 0) return null;\n")
          .append("            return adoptUnsafe(address, factory);\n        }\n");
      return;
    }
    out.append("        /** Null means native creation failed; the consumer is not called. */\n")
        .append("        public static <T> T ")
        .append(r.wrapperName(name))
        .append("(ResourceFactory<T> factory")
        .append(params.isEmpty() ? "" : ", " + String.join(", ", params))
        .append(") {\n")
        .append("            java.util.Objects.requireNonNull(factory);\n")
        .append("            long address = ")
        .append(target)
        .append('(')
        .append(String.join(", ", args))
        .append(").rawValue();\n")
        .append("            if (address == 0) return null;\n")
        .append("            return adoptUnsafe(address, factory);\n        }\n");
  }

  /** What an absent buffer passes: the null pointer, in the buffer's own word carrier. */
  private static final String NULL_POINTER = "org.graalvm.word.WordFactory.nullPointer()";

  /** One acquired buffer of a wrapper: its positional argument and the suffix of its locals. */
  private record Buffer(String name, String suffix, BufferBorrow borrow) {}

  /**
   * The alignment of a pinned {@code byte[]}'s data: an 8-byte object boundary and a 16-byte base.
   */
  private static final long PINNED_ALIGNMENT = 8;

  /**
   * What a present empty buffer lends: a stack byte for a buffer without an align fact, otherwise
   * one rounded up to the fact, since LLVM's {@code align} attribute does not depend on the extent.
   */
  private static String dummy(CallBorrows call, BufferBorrow b) {
    long align = call.align(b);
    if (align <= 1) return "org.graalvm.nativeimage.StackValue.get(1)";
    return "org.graalvm.word.WordFactory.pointer((org.graalvm.nativeimage.StackValue"
        + ".<org.graalvm.word.PointerBase>get("
        + 2 * align
        + ").rawValue() + "
        + (align - 1)
        + ") & -"
        + align
        + "L)";
  }

  /**
   * The off-heap and array wrappers of one function. Buffers are acquired or pinned in parameter
   * order and released in reverse, each in a {@code finally} of its own; other parameters pass
   * through in the carriers of the raw binding. A {@code null} argument for a nullable buffer is an
   * absent buffer: never acquired, pinned or released, and passed as the null pointer with length
   * zero.
   */
  private static void buffers(Module m, CallBorrows call, StringBuilder out) {
    Function f = call.function();
    // Use positional generated names to avoid collisions with consumer parameter names.
    var nativeParams = new ArrayList<String>();
    var arrayParams = new ArrayList<String>();
    var arguments = new ArrayList<String>();
    var buffers = new ArrayList<Buffer>();
    int index = 0;
    for (Parameter p : f.parameters()) {
      String name = "arg" + index++;
      BufferBorrow buffer = call.buffer(p);
      BufferBorrow length = call.length(p);
      if (buffer != null) {
        buffers.add(new Buffer(name, call.suffix(buffer), buffer));
        nativeParams.add("NativeBuffer " + name);
        arrayParams.add("byte[] " + name);
        arguments.add("pointer" + call.suffix(buffer));
      } else if (length != null)
        arguments.add((call.narrow(length) ? "(int) length" : "length") + call.suffix(length));
      else {
        String carrier = NativeImage.qualifiedCarrier(m, p.type());
        nativeParams.add(carrier + " " + name);
        arrayParams.add(carrier + " " + name);
        arguments.add(name);
      }
    }
    String invoke =
        (f.returns() == Scalar.VOID ? "" : "return ")
            + m.nativeClass()
            + "."
            + f.name()
            + "("
            + String.join(", ", arguments)
            + ");";
    String returns = NativeImage.qualifiedCarrier(m, f.returns());
    out.append("    public static ")
        .append(returns)
        .append(' ')
        .append(f.name())
        .append('(')
        .append(String.join(", ", nativeParams))
        .append(") {\n");
    String pad = "        ";
    for (Buffer b : buffers) {
      String s = b.suffix();
      boolean writable = call.writable(b.borrow());
      boolean nullable = call.nullable(b.borrow());
      // What an absent buffer reads as, ahead of each use of a nullable one.
      String absent = nullable ? b.name() + " == null ? 0 : " : "";
      out.append(pad)
          .append(nullable ? "if (" + b.name() + " != null) " : "")
          .append(b.name())
          .append(".acquire(")
          .append(writable)
          .append(");\n")
          .append(pad)
          .append("try {\n")
          .append(pad)
          .append("    long length")
          .append(s)
          .append(" = ")
          .append(absent)
          .append(b.name())
          .append(".byteSize();\n");
      if (call.narrow(b.borrow()))
        out.append(pad)
            .append("    if (length")
            .append(s)
            .append(" > ")
            .append(call.maxLength(b.borrow()))
            .append(") throw new IllegalArgumentException(\"buffer length exceeds ABI range\");\n");
      out.append(pad)
          .append("    long address")
          .append(s)
          .append(" = ")
          .append(absent)
          .append(b.name())
          .append(".address();\n")
          .append(pad)
          .append("    if (length")
          .append(s)
          .append(" < 0 || (address")
          .append(s)
          .append(" == 0 && length")
          .append(s)
          .append(" != 0)) throw new IllegalArgumentException(\"invalid buffer extent\");\n")
          .append(call.alignmentAssertion(b.borrow(), "address" + s, "length" + s, pad + "    "))
          .append(pad)
          .append("    org.graalvm.nativeimage.c.type.CCharPointer pointer")
          .append(s)
          .append(" = ")
          .append(nullable ? b.name() + " == null ? " + NULL_POINTER + " : " : "")
          // A present empty buffer is lent the dummy, whatever address it reports: under an align
          // fact that address may be misaligned, which LLVM's attribute does not excuse.
          .append(call.align(b.borrow()) > 1 ? "length" : "address")
          .append(s)
          .append(" == 0\n")
          .append(pad)
          .append(
              "        ? "
                  + dummy(call, b.borrow())
                  + " : org.graalvm.word.WordFactory.pointer(address")
          .append(s)
          .append(");\n");
      pad += "    ";
    }
    out.append(pad).append(invoke).append('\n');
    for (Buffer b : buffers.reversed()) {
      pad = pad.substring(4);
      out.append(pad)
          .append("} finally {\n")
          .append(pad)
          .append("    ")
          .append(call.nullable(b.borrow()) ? "if (" + b.name() + " != null) " : "")
          .append(b.name())
          .append(".release(")
          .append(call.writable(b.borrow()))
          .append(");\n")
          .append(pad)
          .append("    java.lang.ref.Reference.reachabilityFence(")
          .append(b.name())
          .append(");\n")
          .append(pad)
          .append("}\n");
    }
    out.append("    }\n")
        .append(
            "    /** Array convenience path; caller prevents conflicting concurrent array access."
                + " */\n")
        .append("    public static ")
        .append(returns)
        .append(' ')
        .append(f.name())
        .append('(')
        .append(String.join(", ", arrayParams))
        .append(") {\n");
    // Plain try/finally throughout: try-with-resources compiles to Throwable.addSuppressed, which
    // Truffle's runtime-compilation blocklist rejects on partially evaluated paths (#87).
    // A pinned array's data starts on an 8-byte boundary, so a stricter align fact is met by a
    // copy,
    // which the several-array code below makes.
    if (buffers.size() == 1 && call.align(buffers.getFirst().borrow()) <= PINNED_ALIGNMENT) {
      String name = buffers.getFirst().name();
      if (call.nullable(buffers.getFirst().borrow()))
        out.append("        if (")
            .append(name)
            .append(" == null) {\n            long length = 0;\n")
            .append("            org.graalvm.nativeimage.c.type.CCharPointer pointer = ")
            .append(NULL_POINTER)
            .append(";\n            ")
            .append(invoke)
            .append(f.returns() == Scalar.VOID ? "\n            return;" : "")
            .append("\n        }\n");
      out.append("        long length = ")
          .append(name)
          .append(".length;\n")
          .append(
              "        if (length == 0) {\n"
                  + "            org.graalvm.nativeimage.c.type.CCharPointer pointer ="
                  + " "
                  + dummy(call, buffers.getFirst().borrow())
                  + ";\n"
                  + "            ")
          .append(invoke)
          .append(f.returns() == Scalar.VOID ? "\n            return;" : "")
          .append("\n        }\n")
          .append(
              "        org.graalvm.nativeimage.PinnedObject pin ="
                  + " org.graalvm.nativeimage.PinnedObject.create(")
          .append(name)
          .append(");\n        try {\n")
          .append(
              "            org.graalvm.nativeimage.c.type.CCharPointer pointer ="
                  + " pin.addressOfArrayElement(0);\n")
          .append(
              call.alignmentAssertion(
                  buffers.getFirst().borrow(), "pointer.rawValue()", "length", "            "))
          .append("            ")
          .append(invoke)
          .append("\n        } finally {\n            pin.close();\n        }\n    }\n");
      return;
    }
    // Several arrays: every length is read first, then each non-empty array is pinned in turn; an
    // empty one has no element to pin and gets the stack dummy a present buffer's non-null address
    // needs, and an absent one gets the null pointer.
    for (Buffer b : buffers)
      out.append("        long length")
          .append(b.suffix())
          .append(" = ")
          .append(call.nullable(b.borrow()) ? b.name() + " == null ? 0 : " : "")
          .append(b.name())
          .append(".length;\n");
    pad = "        ";
    for (Buffer b : buffers) {
      String s = b.suffix();
      long align = call.align(b.borrow());
      String absent =
          call.nullable(b.borrow()) ? b.name() + " == null ? " + NULL_POINTER + " : " : "";
      if (align > PINNED_ALIGNMENT) {
        // Copied: native memory rounded up to the fact, filled from the array, and written back
        // (the callee may write a writable buffer) before it is freed.
        out.append(pad)
            .append("org.graalvm.word.Pointer raw")
            .append(s)
            .append(" = length")
            .append(s)
            .append(" == 0 ? org.graalvm.word.WordFactory.nullPointer()\n")
            .append(pad)
            .append(
                "    : org.graalvm.nativeimage.UnmanagedMemory.malloc("
                    + "org.graalvm.word.WordFactory.unsigned(length")
            .append(s)
            .append(" + ")
            .append(align)
            .append("));\n")
            .append(pad)
            .append("org.graalvm.nativeimage.c.type.CCharPointer pointer")
            .append(s)
            .append(" = ")
            .append(absent)
            .append("raw")
            .append(s)
            .append(".isNull()\n")
            .append(pad)
            .append("    ? ")
            .append(dummy(call, b.borrow()))
            .append(" : org.graalvm.word.WordFactory.pointer((raw")
            .append(s)
            .append(".rawValue() + ")
            .append(align - 1)
            .append(") & -")
            .append(align)
            .append("L);\n")
            .append(pad)
            .append("try {\n")
            .append(pad)
            .append("    for (int i")
            .append(s)
            .append(" = 0; i")
            .append(s)
            .append(" < length")
            .append(s)
            .append("; i")
            .append(s)
            .append("++) pointer")
            .append(s)
            .append(".write(i")
            .append(s)
            .append(", ")
            .append(b.name())
            .append("[i")
            .append(s)
            .append("]);\n")
            .append(
                call.alignmentAssertion(
                    b.borrow(), "pointer" + s + ".rawValue()", "length" + s, pad + "    "));
      } else {
        out.append(pad)
            .append("org.graalvm.nativeimage.PinnedObject pin")
            .append(s)
            .append(" = length")
            .append(s)
            .append(" == 0 ? null : org.graalvm.nativeimage.PinnedObject.create(")
            .append(b.name())
            .append(");\n")
            .append(pad)
            .append("try {\n")
            .append(pad)
            .append("    org.graalvm.nativeimage.c.type.CCharPointer pointer")
            .append(s)
            .append(" = ")
            .append(absent)
            .append("pin")
            .append(s)
            .append(" == null\n")
            .append(pad)
            .append("        ? ")
            .append(dummy(call, b.borrow()))
            .append(" : pin")
            .append(s)
            .append(".addressOfArrayElement(0);\n")
            .append(
                call.alignmentAssertion(
                    b.borrow(), "pointer" + s + ".rawValue()", "length" + s, pad + "    "));
      }
      pad += "    ";
    }
    out.append(pad).append(invoke).append('\n');
    for (Buffer b : buffers.reversed()) {
      pad = pad.substring(4);
      String s = b.suffix();
      out.append(pad).append("} finally {\n");
      if (call.align(b.borrow()) > PINNED_ALIGNMENT) {
        out.append(pad).append("    if (raw").append(s).append(".isNonNull()) {\n");
        if (call.writable(b.borrow()))
          out.append(pad)
              .append("        for (int i")
              .append(s)
              .append(" = 0; i")
              .append(s)
              .append(" < length")
              .append(s)
              .append("; i")
              .append(s)
              .append("++) ")
              .append(b.name())
              .append("[i")
              .append(s)
              .append("] = pointer")
              .append(s)
              .append(".read(i")
              .append(s)
              .append(");\n");
        out.append(pad)
            .append("        org.graalvm.nativeimage.UnmanagedMemory.free(raw")
            .append(s)
            .append(");\n")
            .append(pad)
            .append("    }\n");
      } else
        out.append(pad)
            .append("    if (pin")
            .append(s)
            .append(" != null) pin")
            .append(s)
            .append(".close();\n");
      out.append(pad).append("}\n");
    }
    out.append("    }\n");
  }
}
